package com.lamggm.rospocket;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31)
public class GaugeLayoutTest {
 @Test public void legacyLayoutLoadsWithoutDisplayAndMalformedDisplayNeverPersists()throws Exception{JSONObject legacy=new JSONObject(DashboardLayout.defaults().encode()).put("schema",1);legacy.remove("columns");for(int i=0;i<7;i++){legacy.getJSONArray("cards").getJSONObject(i).remove("display");legacy.getJSONArray("cards").getJSONObject(i).remove("name");legacy.getJSONArray("cards").getJSONObject(i).remove("column");legacy.getJSONArray("cards").getJSONObject(i).remove("row");}assertEquals("number",DashboardLayout.decode(legacy.toString()).get("watch0").display.mode);assertThrows(IllegalArgumentException.class,()->new DashboardLayout.Display("gauge","data",1,1,""));assertThrows(IllegalArgumentException.class,()->new DashboardLayout.Display("bar","data",Double.NaN,2,""));assertThrows(IllegalArgumentException.class,()->new DashboardLayout.Display("bar","data",-Double.MAX_VALUE,Double.MAX_VALUE,""));assertThrows(IllegalArgumentException.class,()->new DashboardLayout.Display("bar","bad path",0,10,""));assertThrows(IllegalArgumentException.class,()->DashboardLayout.defaults().display("robot",DashboardLayout.Display.defaults()));JSONObject invalid=new JSONObject(DashboardLayout.defaults().encode());invalid.getJSONArray("cards").getJSONObject(0).getJSONObject("display").put("min",false);assertThrows(IllegalArgumentException.class,()->DashboardLayout.decode(invalid.toString()));}
 @Test public void explicitVisualizationSurvivesLayoutResizeReorderAndRoundTrip()throws Exception{
  JSONObject root=new JSONObject(DashboardLayout.defaults().encode()).put("schema",2);root.remove("columns");for(int i=0;i<7;i++){root.getJSONArray("cards").getJSONObject(i).remove("name");root.getJSONArray("cards").getJSONObject(i).remove("column");root.getJSONArray("cards").getJSONObject(i).remove("row");}JSONObject row=root.getJSONArray("cards").getJSONObject(0);
  row.put("display",new JSONObject().put("mode","gauge").put("path","linear.x").put("min",-2).put("max",8).put("unit","m/s"));
  DashboardLayout read=DashboardLayout.decode(root.toString()).resize("watch0",2,2).before("watch0","plot");JSONObject result=new JSONObject(read.encode());assertEquals(4,result.getInt("schema"));JSONObject saved=null;for(int i=0;i<7;i++)if(result.getJSONArray("cards").getJSONObject(i).getString("id").equals("watch0"))saved=result.getJSONArray("cards").getJSONObject(i).getJSONObject("display");assertNotNull(saved);assertEquals("gauge",saved.getString("mode"));assertEquals("linear.x",saved.getString("path"));assertEquals(-2,saved.getDouble("min"),0);assertEquals("m/s",saved.getString("unit"));assertEquals(read.encode(),DashboardLayout.decode(read.encode()).encode());
 }
}
